// Copies JSON owned by other folders (response fixtures, thresholds, labels, schemes) into
// src/services/generated so the frontend builds from the same files the backend uses.
// Run automatically by predev/prebuild/pretest. Never edit src/services/generated by hand.
import { cpSync, existsSync, mkdirSync, readdirSync, writeFileSync, readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const root = join(here, '..');
const out = join(here, 'src', 'services', 'generated');
mkdirSync(join(out, 'fixtures'), { recursive: true });

const fixtures = join(root, 'backend', 'tests', 'fixtures');
for (const f of readdirSync(fixtures)) {
  if (f.endsWith('.json')) cpSync(join(fixtures, f), join(out, 'fixtures', f));
}
const thresholds = join(root, 'ml', 'models', 'thresholds.json');
writeFileSync(
  join(out, 'thresholds.json'),
  existsSync(thresholds)
    ? readFileSync(thresholds)
    : JSON.stringify({ unknown_photo: 0.45, likely_high: 0.7, likely_high_margin: 0.3, likely_medium: 0.5 }),
);
cpSync(join(root, 'ml', 'models', 'labels.json'), join(out, 'labels.json'));
// Only used in VITE_USE_FIXTURES=1 mode (no backend).
cpSync(join(root, 'backend', 'knowledge_base', 'schemes.json'), join(out, 'schemes.json'));
console.log('sync-content: copied fixtures, thresholds, labels, schemes');
